/**
 * @suppress
 */
public object FfiConverterTypeBlobStore: FfiConverter<BlobStore, Long> {
    internal val handleMap = UniffiHandleMap<BlobStore>()

    override fun lower(value: BlobStore): Long {
        if (value is BlobStoreImpl) {
             // Rust-implemented object.  Clone the handle and return it
            return value.uniffiCloneHandle()
         } else {
            // Kotlin object, generate a new vtable handle and return that.
            return handleMap.insert(value)
         }
    }

    override fun lift(value: Long): BlobStore {
        if ((value and 1.toLong()) == 0.toLong()) {
            // Rust-generated handle, construct a new class that uses the handle to implement the
            // interface
            return BlobStoreImpl(UniffiWithHandle, value)
        } else {
            // Kotlin-generated handle, get the object from the handle map
            return handleMap.remove(value)
        }
    }

    override fun read(buf: ByteBuffer): BlobStore {
        return lift(buf.getLong())
    }

    override fun allocationSize(value: BlobStore) = 8UL

    override fun write(value: BlobStore, buf: ByteBuffer) {
        buf.putLong(lower(value))
    }
}


