// method is slow, and/or there are many objects to cleanup, and it's on a low end Android device, then the cleaner
// thread may be starved, and the app will leak memory.
//
// In this case, `destroy`ing manually may be a better solution.
//
// The cleaner can live side by side with the manual calling of `destroy`. In the order of responsiveness, uniffi objects
// with Rust peers are reclaimed:
//
// 1. By calling the `destroy` method of the object, which calls `rustObject.free()`. If that doesn't happen:
// 2. When the object becomes unreachable, AND the Cleaner thread gets to call `rustObject.free()`. If the thread is starved then:
// 3. The memory is reclaimed when the process terminates.
//
// [1] https://stackoverflow.com/questions/24376768/can-java-finalize-an-object-when-it-is-still-in-scope/24380219
//


/**
 * Maps screens to windows (desktop) or nav stacks and sheets (phones).
 */
public interface WindowHost {
    
    /**
     * Show `screen` of `app` (`params` = a JSON object).
     */
    fun `present`(`app`: kotlin.String, `screen`: kotlin.String, `paramsJson`: kotlin.String, `how`: Presentation)
    
    companion object
}

/**
 * Maps screens to windows (desktop) or nav stacks and sheets (phones).
 */
open class WindowHostImpl: Disposable, AutoCloseable, WindowHost
{

    @Suppress("UNUSED_PARAMETER")
    /**
     * @suppress
     */
    constructor(withHandle: UniffiWithHandle, handle: Long) {
        this.handle = handle
        this.cleanable = UniffiLib.CLEANER.register(this, UniffiCleanAction(handle))
    }

    /**
     * @suppress
     *
     * This constructor can be used to instantiate a fake object. Only used for tests. Any
     * attempt to actually use an object constructed this way will fail as there is no
     * connected Rust object.
     */
    @Suppress("UNUSED_PARAMETER")
    constructor(noHandle: NoHandle) {
        this.handle = 0
        this.cleanable = null
    }

    protected val handle: Long
    protected val cleanable: UniffiCleaner.Cleanable?

    private val wasDestroyed = AtomicBoolean(false)
    private val callCounter = AtomicLong(1)

    /**
     * Whether the current object has been destroyed and its reference is gone in the Rust side.
     */
    val uniffiIsDestroyed: Boolean get() = wasDestroyed.get()

    override fun destroy() {
        // Only allow a single call to this method.
        // TODO: maybe we should log a warning if called more than once?
        if (this.wasDestroyed.compareAndSet(false, true)) {
            // This decrement always matches the initial count of 1 given at creation time.
            if (this.callCounter.decrementAndGet() == 0L) {
                cleanable?.clean()
            }
        }
    }

    @Synchronized
    override fun close() {
        this.destroy()
    }

    internal inline fun <R> callWithHandle(block: (handle: Long) -> R): R {
        // Check and increment the call counter, to keep the object alive.
        // This needs a compare-and-set retry loop in case of concurrent updates.
        do {
            val c = this.callCounter.get()
            if (c == 0L) {
                throw IllegalStateException("${this.javaClass.simpleName} object has already been destroyed")
            }
            if (c == Long.MAX_VALUE) {
                throw IllegalStateException("${this.javaClass.simpleName} call counter would overflow")
            }
        } while (! this.callCounter.compareAndSet(c, c + 1L))
        // Now we can safely do the method call without the handle being freed concurrently.
        try {
            return block(this.uniffiCloneHandle())
        } finally {
            // This decrement always matches the increment we performed above.
            if (this.callCounter.decrementAndGet() == 0L) {
                cleanable?.clean()
            }
        }
    }

    // Use a static inner class instead of a closure so as not to accidentally
    // capture `this` as part of the cleanable's action.
    private class UniffiCleanAction(private val handle: Long) : Runnable {
        override fun run() {
            if (handle == 0.toLong()) {
                // Fake object created with `NoHandle`, don't try to free.
                return;
            }
            uniffiRustCall { status ->
                UniffiLib.uniffi_eengine_ffi_fn_free_windowhost(handle, status)
            }
        }
    }

    /**
     * @suppress
     */
    fun uniffiCloneHandle(): Long {
        if (handle == 0.toLong()) {
            throw InternalException("uniffiCloneHandle() called on NoHandle object");
        }
        return uniffiRustCall() { status ->
            UniffiLib.uniffi_eengine_ffi_fn_clone_windowhost(handle, status)
        }
    }

    
    /**
     * Show `screen` of `app` (`params` = a JSON object).
     */override fun `present`(`app`: kotlin.String, `screen`: kotlin.String, `paramsJson`: kotlin.String, `how`: Presentation)
        = 
    callWithHandle {
    uniffiRustCall() { _status ->
    UniffiLib.uniffi_eengine_ffi_fn_method_windowhost_present(
        it,
        
        FfiConverterString.lower(`app`),
        FfiConverterString.lower(`screen`),
        FfiConverterString.lower(`paramsJson`),
        FfiConverterTypePresentation.lower(`how`),_status)
}
    }
    
    

    

    


    
    
    /**
     * @suppress
     */
    companion object
    
}



// Put the implementation in an object so we don't pollute the top-level namespace
internal object uniffiCallbackInterfaceWindowHost {
    internal object `present`: UniffiCallbackInterfaceWindowHostMethod0 {
        override fun callback(`uniffiHandle`: Long,`app`: RustBuffer.ByValue,`screen`: RustBuffer.ByValue,`paramsJson`: RustBuffer.ByValue,`how`: RustBuffer.ByValue,`uniffiOutReturn`: Pointer,uniffiCallStatus: UniffiRustCallStatus,) {
            val uniffiObj = FfiConverterTypeWindowHost.handleMap.get(uniffiHandle)
            val makeCall = { ->
                uniffiObj.`present`(
                    FfiConverterString.lift(`app`),
                    FfiConverterString.lift(`screen`),
                    FfiConverterString.lift(`paramsJson`),
                    FfiConverterTypePresentation.lift(`how`),
                )
            }
            val writeReturn = { _: Unit -> Unit }
            uniffiTraitInterfaceCall(uniffiCallStatus, makeCall, writeReturn)
        }
    }

    internal object uniffiFree: UniffiCallbackInterfaceFree {
        override fun callback(handle: Long) {
            FfiConverterTypeWindowHost.handleMap.remove(handle)
        }
    }

    internal object uniffiClone: UniffiCallbackInterfaceClone {
        override fun callback(handle: Long): Long {
            return FfiConverterTypeWindowHost.handleMap.clone(handle)
        }
    }

    internal var vtable = UniffiVTableCallbackInterfaceWindowHost.UniffiByValue(
        uniffiFree,
        uniffiClone,
        `present`,
    )

    // Registers the foreign callback with the Rust side.
    // This method is generated for each callback interface.
    internal fun register(lib: UniffiLib) {
        lib.uniffi_eengine_ffi_fn_init_callback_vtable_windowhost(vtable)
    }
}

/**
 * @suppress
 */
public object FfiConverterTypeWindowHost: FfiConverter<WindowHost, Long> {
    internal val handleMap = UniffiHandleMap<WindowHost>()

    override fun lower(value: WindowHost): Long {
        if (value is WindowHostImpl) {
             // Rust-implemented object.  Clone the handle and return it
            return value.uniffiCloneHandle()
         } else {
            // Kotlin object, generate a new vtable handle and return that.
            return handleMap.insert(value)
         }
    }

    override fun lift(value: Long): WindowHost {
        if ((value and 1.toLong()) == 0.toLong()) {
            // Rust-generated handle, construct a new class that uses the handle to implement the
            // interface
            return WindowHostImpl(UniffiWithHandle, value)
        } else {
            // Kotlin-generated handle, get the object from the handle map
            return handleMap.remove(value)
        }
    }

    override fun read(buf: ByteBuffer): WindowHost {
        return lift(buf.getLong())
    }

    override fun allocationSize(value: WindowHost) = 8UL

    override fun write(value: WindowHost, buf: ByteBuffer) {
        buf.putLong(lower(value))
    }
}



