sealed class CallResult {
    
    /**
     * The call's value (JSON).
     */
    data class Value(
        val `json`: kotlin.String) : CallResult()
        
    {
        

        companion object
    }
    
    /**
     * The person decides first: paint `sheet`, then `answerConsent` with
     * the same call and `verdictJson`.
     */
    data class Ask(
        val `verdictJson`: kotlin.String, 
        val `sheet`: at.exponential.engine.ffi.ConsentSheet) : CallResult()
        
    {
        

        companion object
    }
    
    /**
     * Refused (the failed-action toast's reason).
     */
    data class Refused(
        val `code`: kotlin.String, 
        val `message`: kotlin.String) : CallResult()
        
    {
        

        companion object
    }
    

    

    
    


    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeCallResult : FfiConverterRustBuffer<CallResult>{
    override fun read(buf: ByteBuffer): CallResult {
        return when(buf.getInt()) {
            1 -> CallResult.Value(
                FfiConverterString.read(buf),
                )
            2 -> CallResult.Ask(
                FfiConverterString.read(buf),
                FfiConverterTypeConsentSheet.read(buf),
                )
            3 -> CallResult.Refused(
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: CallResult): ULong = when(value) {
        is CallResult.Value -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`json`)
            )
        }
        is CallResult.Ask -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`verdictJson`)
                + FfiConverterTypeConsentSheet.allocationSize(value.`sheet`)
            )
        }
        is CallResult.Refused -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`code`)
                + FfiConverterString.allocationSize(value.`message`)
            )
        }
    }

    override fun write(value: CallResult, buf: ByteBuffer) {
        when(value) {
            is CallResult.Value -> {
                buf.putInt(1)
                FfiConverterString.write(value.`json`, buf)
                Unit
            }
            is CallResult.Ask -> {
                buf.putInt(2)
                FfiConverterString.write(value.`verdictJson`, buf)
                FfiConverterTypeConsentSheet.write(value.`sheet`, buf)
                Unit
            }
            is CallResult.Refused -> {
                buf.putInt(3)
                FfiConverterString.write(value.`code`, buf)
                FfiConverterString.write(value.`message`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}





