        override val message
            get() = "reason=${ `reason` }"
    }
    
    /**
     * The package did not load: `kind` = `signature` | `invalid`,
     * `issuesJson` = `[{path, message}]`.
     */
    class Load(
        
        val `kind`: kotlin.String, 
        
        val `issuesJson`: kotlin.String
        ) : EngineException() {
        override val message
            get() = "kind=${ `kind` }, issuesJson=${ `issuesJson` }"
    }
    
    /**
     * A provider's refusal or failure (eCore's shape).
     */
    class Failure(
        
        val `code`: kotlin.String, 
        
        val `reason`: kotlin.String
        ) : EngineException() {
        override val message
            get() = "code=${ `code` }, reason=${ `reason` }"
    }
    

    


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<EngineException> {
        override fun lift(error_buf: RustBuffer.ByValue): EngineException = FfiConverterTypeEngineError.lift(error_buf)
    }

    
}

