        val `message`: kotlin.String?, 
        val `invalid`: kotlin.Boolean) : Submitted()
        
    {
        

        companion object
    }
    
    /**
     * Offline, behind others, a retry or a drop: the answer from the entry.
     */
    data class Queued(
        val `answerJson`: kotlin.String) : Submitted()
        
    {
        

        companion object
    }
    

    

    
    


    companion object
}

